import{_ as t,H as a,f as n,i as s}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"加餐01｜Text to SQL：自然语言写SQL查询","description":"","frontmatter":{},"headers":[{"level":2,"title":"Text to SQL 技术","slug":"text-to-sql-技术","link":"#text-to-sql-技术","children":[]},{"level":2,"title":"LLM 模型选择","slug":"llm-模型选择","link":"#llm-模型选择","children":[{"level":3,"title":"闭源模型","slug":"闭源模型","link":"#闭源模型","children":[]},{"level":3,"title":"开源模型","slug":"开源模型","link":"#开源模型","children":[]},{"level":3,"title":"代码大模型","slug":"代码大模型","link":"#代码大模型","children":[]}]},{"level":2,"title":"Text to SQL 工作流程优化","slug":"text-to-sql-工作流程优化","link":"#text-to-sql-工作流程优化","children":[]}],"relativePath":"SQL必知必会/加餐01｜TexttoSQL：自然语言写SQL查询.md","filePath":"SQL必知必会/加餐01｜TexttoSQL：自然语言写SQL查询.md","lastUpdated":1779816304000}'),l={name:"SQL必知必会/加餐01｜TexttoSQL：自然语言写SQL查询.md"};function i(p,e,o,r,c,u){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="加餐01-text-to-sql-自然语言写sql查询" tabindex="-1">加餐01｜Text to SQL：自然语言写SQL查询 <a class="header-anchor" href="#加餐01-text-to-sql-自然语言写sql查询" aria-label="Permalink to &quot;加餐01｜Text to SQL：自然语言写SQL查询&quot;">​</a></h1><p>你好，我是陈博士。</p><p>在AI时代，很多业务人员可以不写SQL就进行数据查询，他们可以通过自然语言向数据库进行提问。这依赖于一种技术，称为Text to SQL。</p><h2 id="text-to-sql-技术" tabindex="-1"><strong>Text to SQL 技术</strong> <a class="header-anchor" href="#text-to-sql-技术" aria-label="Permalink to &quot;**Text to SQL 技术**&quot;">​</a></h2><p>Text-to-SQL（文本转 SQL）是将自然语言问题自动转换为结构化的 SQL 查询语句，这样可以让用户更直观的与数据库进行交互。Text-to-SQL的技术演变经历了3个阶段。</p><ul><li><p><strong>早期阶段</strong>：依赖于人工编写的规则模板，来匹配自然语言和SQL语句之间的对应关系。</p></li><li><p><strong>机器学习阶段：</strong> 采用序列到序列模型等机器学习方法，来学习自然语言和SQL之间的映射关系。</p></li><li><p><strong>LLM 阶段：</strong> 借助 LLM 强大的语言理解和代码生成能力，利用提示工程、微调等方法将 Text-to-SQL 性能提升到新的高度。</p></li></ul><p>我们目前已处于LLM阶段，基于 LLM 的 Text-to-SQL 系统会包含以下几个步骤：</p><ul><li><p><strong>自然语言理解：</strong> 分析用户输入的自然语言问题，理解其意图和语义。</p></li><li><p><strong>模式链接：</strong> 将问题中的实体与数据库模式中的表和列进行链接。</p></li><li><p><strong>SQL 生成：</strong> 根据理解的语义和模式链接结果，生成相应的 SQL 查询语句。</p></li><li><p><strong>SQL 执行：</strong> 在数据库上执行SQL查询，将结果返回给用户。</p></li></ul><h2 id="llm-模型选择" tabindex="-1"><strong>LLM 模型选择</strong> <a class="header-anchor" href="#llm-模型选择" aria-label="Permalink to &quot;**LLM 模型选择**&quot;">​</a></h2><p>下面我按照闭源、开源、代码大模型，推荐一些我比较常用的大模型。</p><h3 id="闭源模型" tabindex="-1"><strong>闭源模型</strong> <a class="header-anchor" href="#闭源模型" aria-label="Permalink to &quot;**闭源模型**&quot;">​</a></h3><ul><li><p>GPT-o1-mini：o1模型开启了新的Scaling Law，更专注于推理阶段，在编程和Text to SQL中能力优于GPT-4o，同时mini模型速度更快，价格更低。</p></li><li><p>Claude 3.5-sonnet：Anthropic公司发布，支持20万token上下文，性能超过GPT-4o，在Cursor中使用非常顺滑。</p></li><li><p>Gemini Pro-1.5：性能强悍，支持100万token上下文。</p></li><li><p>Qwen-Turbo：支持100万token上下文，速度快，价格非常便宜。</p></li></ul><h3 id="开源模型" tabindex="-1"><strong>开源模型</strong> <a class="header-anchor" href="#开源模型" aria-label="Permalink to &quot;**开源模型**&quot;">​</a></h3><ul><li>Qwen：Qwen系列有0.5B、1.5B、3B、7B、14B、32B、72B等多种尺寸，性能优于Llama3.1。</li></ul><h3 id="代码大模型" tabindex="-1"><strong>代码大模型</strong> <a class="header-anchor" href="#代码大模型" aria-label="Permalink to &quot;**代码大模型**&quot;">​</a></h3><ul><li><p>Qwen-coder：能力强，接近闭源一线大模型，其中Qwen2.5-Coder-32B能力与GPT-4o持平，略落后于Claude 3.5 Haiku。</p></li><li><p>CodeGeeX：智谱开源的代码大模型，基于GLM底座，性能卓越，在 VSCode 等编辑器中可以找到对应的插件。</p></li><li><p>SQLCoder：专为 SQL 生成而设计的开源模型，但是维护更新慢。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/7b9ea61b3230329e145112223b4213f3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/7b9ea61b3230329e145112223b4213f3.png" alt="图片"></a></p><p>如果是基于数据安全性考虑，可以在本地部署Qwen-7B/72B等开源模型，同时可以进行对话和撰写SQL。如果很重视代码质量（包括SQL），可以部署Qwen-Coder专门用于代码生成。</p><p>如果查询的数据是公开的，或者不需要过多考虑数据安全性，可以使用Qwen-Turbo，性能和价格都非常好，通过API调用省去了自己部署的成本。当然你也可以调用o1、Gemini、Claude 等国外最先进的模型，进行SQL的对比和优化。</p><h2 id="text-to-sql-工作流程优化" tabindex="-1"><strong>Text to SQL 工作流程优化</strong> <a class="header-anchor" href="#text-to-sql-工作流程优化" aria-label="Permalink to &quot;**Text to SQL 工作流程优化**&quot;">​</a></h2><p>为了让LLM生成高质量的SQL查询语句，你可以使用以下的技术：</p><ul><li><p>提示工程（Prompt Engineering）：设计更有效的提示模板，以引导 LLM 生成更准确的 SQL 查询语句。</p></li><li><p>上下文学习（In-Context Learning）：在提示中提供一些示例，以帮助 LLM 更好地理解任务。</p></li><li><p>推理增强：使用一些技术来增强 LLM 的推理能力，例如使用多步推理方法。</p></li><li><p>执行优化：对生成的 SQL 查询语句进行优化，以提高其执行效率。</p></li></ul><p>这里我们重点讲解下，如何通过prompt更有效地驱动LLM编写SQL。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/736036b14843511b18595f321cc2b598.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/736036b14843511b18595f321cc2b598.jpg" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/e34cbda88888496d18b70f039527179c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/e34cbda88888496d18b70f039527179c.png" alt="图片"></a></p><p>SQL prompt template 撰写：</p><p>方法1：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prompt = f&quot;&quot;&quot;# language: SQL</span></span>
<span class="line"><span>/*</span></span>
<span class="line"><span>{query}你需要先判断需要哪个数据表和字段，然后基于它们编写SQL。数据库中有以下数据表：</span></span>
<span class="line"><span>=====</span></span>
<span class="line"><span>{table_description}</span></span>
<span class="line"><span>*/</span></span></code></pre></div><p>方法2：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prompt = f&quot;&quot;&quot;</span></span>
<span class="line"><span>-- language: SQL</span></span>
<span class="line"><span>/*{query}</span></span>
<span class="line"><span>以下是数据表</span></span>
<span class="line"><span>=====</span></span>
<span class="line"><span>{table_description}</span></span>
<span class="line"><span>=====</span></span>
<span class="line"><span>编写一条SQL: {query}</span></span>
<span class="line"><span>*/&quot;&quot;&quot;</span></span></code></pre></div><p>方法3：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prompt = f&quot;&quot;&quot;-- language: SQL</span></span>
<span class="line"><span>### Question: {query}</span></span>
<span class="line"><span>### Input: {create_sql}</span></span>
<span class="line"><span>### Response:</span></span>
<span class="line"><span>Here is the SQL query I have generated to answer the question \`{query}\`:</span></span>
<span class="line"><span>\`\`\`sql</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span></code></pre></div><p><strong>说明：</strong></p><ul><li>table_description 代表中文的数据表说明</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/2ac5d2b4a8602b0bf099d9dafa97de2e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/2ac5d2b4a8602b0bf099d9dafa97de2e.png" alt="图片"></a></p><ul><li>create_sql 代表建表语句</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/0yyf6f7cdffyyfa05c98f623fbcd837e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/834235/0yyf6f7cdffyyfa05c98f623fbcd837e.png" alt="图片"></a></p><ul><li>query 是用户查询的问题</li></ul><p><strong>这里我想请你先思考下：你觉得方法 1-3，哪个写法更容易让 LLM 生成高质量的 SQL？</strong></p><p>揭晓答案，方法3的SQL生成质量最高，这是因为：</p><ul><li><p>create_sql建表语句更适合LLM理解数据表的内容，而且携带了更多的字段定义信息。大模型通过几十亿行的代码训练，包括SQL代码，所以SQL建表语句对于大模型来说更容易理解。</p></li><li><p>language：SQL前面的注释要用 --，因为SQL的注释是 --，而Python会用#进行注释。</p></li><li><p>如果我们使用的是代码大模型，它的本质是代码补全，因此最后一句 \`\`\`sql 可以让大模型直接写出SQL。否则大模型有可能会在前面进行一堆文字描述，然后才写SQL，你需要对后面的SQL专门进行解析。</p></li></ul><p>我对表格中的10个任务都采用方法1-3进行了实验，在CodeGeeX2-6B的大模型下，采用方法3可以得到10个全对的结果，而采用方法1和方法2，只对了8个。所以你能看出， <strong>高质量的 prompt template 可以让 LLM 生成高质量的 SQL。</strong></p><p>那么，在接下来的几节课中，我将给你讲述不同场景下的SQL查询需求。当然通过这些场景示例，你也可以看到Text to SQL的撰写能力。另外我也建议你，作为数据分析师，掌握基本的SQL语法还是很有必要的，因为大模型现在还很难做到100%正确。此外自己掌握SQL撰写能力，也有助于SQL语句的校验和优化，当然对于prompt的撰写也是很有帮助的。</p><p>好，这节课就到这里，如果今天的内容对你有所帮助，也欢迎你转发给有需要的朋友，一起学习。我们下节课再见！</p>`,44)])])}const L=t(l,[["render",i]]);export{h as __pageData,L as default};
